import sys
sys.setrecursionlimit(300000)
from collections import deque
n,m=map(int,input().split())
adj=[[] for _ in range(n+1)]
for idx in range(m):
    u,v=map(int,input().split())
    adj[u].append((v,idx))
    adj[v].append((u,idx))
disc=[0]*(n+1)
low=[0]*(n+1)
visited=[False]*(n+1)
timer=[1]
is_bridge=[False]*m
def dfs(u,pe):
    visited[u]=True
    disc[u]=low[u]=timer[0]
    timer[0]+=1
    for v,ei in adj[u]:
        if ei==pe:
            continue
        if visited[v]:
            low[u]=min(low[u],disc[v])
        else:
            dfs(v,ei)
            low[u]=min(low[u],low[v])
            if low[v]>disc[u]:
                is_bridge[ei]=True
for s in range(1,n+1):
    if not visited[s]:
        dfs(s,-1)
seen=[False]*(n+1)
comp=0
for s in range(1,n+1):
    if not seen[s]:
        comp+=1
        seen[s]=True
        dq=deque([s])
        while dq:
            x=dq.popleft()
            for y,ei in adj[x]:
                if not is_bridge[ei] and not seen[y]:
                    seen[y]=True
                    dq.append(y)
print(comp)

