        ok=False
        for _ in range(r-1):
            x=x*x%n
            if x==n-1:
                ok=True
                break
        if not ok:
            return False
    return True
def pollard(n):
    if n%2==0:
        return 2
    x=2
    y=2
    c=1
    while True:
        x=(x*x+c)%n
        y=(y*y+c)%n
        y=(y*y+c)%n
        d=math.gcd(abs(x-y),n)
        if d!=1:
            if d==n:
                c+=1
                x=2
                y=2
                continue
            return d
