n,m=map(int,input().split())
N=2*n
g=[[] for _ in range(N)]
def node(lit):
    i=abs(lit)-1
    return 2*i if lit>0 else 2*i+1
for _ in range(m):
    a,b=map(int,input().split())
    g[node(-a)].append(node(b))
    g[node(-b)].append(node(a))
rg=[[] for _ in range(N)]
for u in range(N):
    for v in g[u]:
        rg[v].append(u)
visited=[False]*N
order=[]
for s in range(N):
    if not visited[s]:
        stack=[(s,0)]
        visited[s]=True
        while stack:
            nd,idx=stack.pop()
            if idx<len(g[nd]):
                stack.append((nd,idx+1))
                nx=g[nd][idx]
                if not visited[nx]:
                    visited[nx]=True
                    stack.append((nx,0))
            else:
                order.append(nd)
comp=[-1]*N
c=0
for s in reversed(order):
    if comp[s]==-1:
        stack=[s]
        comp[s]=c
        while stack:
            x=stack.pop()
            for y in rg[x]:
                if comp[y]==-1:
