    if depth[a]<depth[b]:
        a,b=b,a
    d=depth[a]-depth[b]
    for k in range(LOG):
        if (d>>k)&1:
            a=up[k][a]
    if a==b:
        return a
    for k in range(LOG-1,-1,-1):
        if up[k][a]!=up[k][b]:
            a=up[k][a]
            b=up[k][b]
    return up[0][a]
