@lru_cache(maxsize=None)
def fs(disks,pegs):
    if disks==0:
        return 0
    if disks==1:
        return 1
    if pegs==3:
        return 2**disks-1
    best=None
    for k in range(1,disks):
        cost=2*fs(k,pegs)+fs(disks-k,pegs-1)
        if best is None or cost<best:
            best=cost
    return best
