    remaining=n
    while remaining>2:
        sz=len(leaves)
        remaining-=sz
        for _ in range(sz):
            leaf=leaves.popleft()
            for nb in g[leaf]:
                deg[nb]-=1
                if deg[nb]==1:
                    leaves.append(nb)
    print(remaining)

