from functools import lru_cache
n=int(input())
@lru_cache(maxsize=None)
def solve(x):
    if x<=1:
        return 0
    best=solve(x-1)+1
    if x%2==0:
        best=min(best,solve(x//2)+1)
    if x%3==0:
        best=min(best,solve(x//3)+1)
    return best
print(solve(n))

