    sm[node]+=v*ln[node]
    lz[node]+=v
def push(node):
    if lz[node]!=0:
        apply(2*node,lz[node])
        apply(2*node+1,lz[node])
        lz[node]=0
def add(node,nl,nr,l,r,v):
    if r<nl or nr<l:
        return
    if l<=nl and nr<=r:
        apply(node,v)
        return
    push(node)
    mid=(nl+nr)//2
    add(2*node,nl,mid,l,r,v)
    add(2*node+1,mid+1,nr,l,r,v)
    sm[node]=sm[2*node]+sm[2*node+1]
