    if r<nl or nr<l:
        return 0
    if l<=nl and nr<=r:
        return sm[node]
    push(node)
    mid=(nl+nr)//2
    return qsum(2*node,nl,mid,l,r)+qsum(2*node+1,mid+1,nr,l,r)
