from collections import deque,defaultdict
n,m,s,t=map(int,input().split())
edges=[]
for _ in range(m):
    u,v=map(int,input().split())
    edges.append((u,v))
if s==t:
    print(0)
else:
    cap=defaultdict(int)
    adj=defaultdict(list)
    def add(u,v,c):
        if v not in adj[u]:
            adj[u].append(v)
        if u not in adj[v]:
            adj[v].append(u)
        cap[(u,v)]+=c
    for v in range(1,n+1):
        add(2*v,2*v+1,10**9 if v in (s,t) else 1)
    for u,v in edges:
        add(2*u+1,2*v,1)
        add(2*v+1,2*u,1)
    S,T=2*s,2*t+1
    flow=0
    while True:
        par={S:None}
        q=deque([S])
        while q:
            x=q.popleft()
            if x==T:
                break
            for y in adj[x]:
                if y not in par and cap[(x,y)]>0:
                    par[y]=x
                    q.append(y)
        if T not in par:
            break
        x=T
        while par[x] is not None:
            p=par[x]
            cap[(p,x)]-=1
            cap[(x,p)]+=1
            x=p
        flow+=1
    print(flow)

