n=int(input())
pts=[tuple(map(int,input().split())) for _ in range(n)]
P=sorted(set(pts))
def cross(o,a,b):
    return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
def hull(P):
    if len(P)<=2:
        return P
    lo=[]
    for p in P:
        while len(lo)>=2 and cross(lo[-2],lo[-1],p)<=0:
            lo.pop()
        lo.append(p)
    up=[]
    for p in reversed(P):
        while len(up)>=2 and cross(up[-2],up[-1],p)<=0:
            up.pop()
        up.append(p)
    return lo[:-1]+up[:-1]
H=hull(P)
def inside(q):
    m=len(H)
    if m<3:
        return False
    for i in range(m):
        if cross(H[i],H[(i+1)%m],q)<=0:
            return False
    return True
print(sum(1 for q in pts if inside(q)))

