import heapq
h,w=map(int,input().split())
g=[list(map(int,input().split())) for _ in range(h)]
seen=[[False]*w for _ in range(h)]
pq=[]
for i in range(h):
    for j in range(w):
        if i in (0,h-1) or j in (0,w-1):
            seen[i][j]=True
            heapq.heappush(pq,(g[i][j],i,j))
water=0
while pq:
    lvl,i,j=heapq.heappop(pq)
    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
        ni,nj=i+di,j+dj
        if 0<=ni<h and 0<=nj<w and not seen[ni][nj]:
            seen[ni][nj]=True
            if g[ni][nj]<lvl:
                water+=lvl-g[ni][nj]
                heapq.heappush(pq,(lvl,ni,nj))
            else:
                heapq.heappush(pq,(g[ni][nj],ni,nj))
print(water)

