import heapq
n=int(input())
words=[input() for _ in range(n)]
letters=sorted(set("".join(words)))
adj={c:set() for c in letters}
indeg={c:0 for c in letters}
bad=False
for a,b in zip(words,words[1:]):
    i=0
    while i<len(a) and i<len(b) and a[i]==b[i]:
        i+=1
    if i<len(a) and i<len(b):
        if b[i] not in adj[a[i]]:
            adj[a[i]].add(b[i])
            indeg[b[i]]+=1
    elif len(a)>len(b):
        bad=True
if bad:
    print(-1)
else:
    h=[c for c in letters if indeg[c]==0]
    heapq.heapify(h)
    out=[]
    while h:
        c=heapq.heappop(h)
        out.append(c)
        for y in sorted(adj[c]):
            indeg[y]-=1
            if indeg[y]==0:
                heapq.heappush(h,y)
    print("".join(out) if len(out)==len(letters) else -1)

