    u,v,w=map(int,input().split())
    total+=w
    deg[u]+=1
    deg[v]+=1
    if w<d[u][v]:
        d[u][v]=w
        d[v][u]=w
for k in range(1,n+1):
    for i in range(1,n+1):
        for j in range(1,n+1):
            if d[i][k]+d[k][j]<d[i][j]:
                d[i][j]=d[i][k]+d[k][j]
odds=[v for v in range(1,n+1) if deg[v]%2]
k=len(odds)
memo={}
def match(mask):
    if mask==(1<<k)-1:
        return 0
    if mask in memo:
        return memo[mask]
    i=0
    while mask>>i&1:
        i+=1
    best=INF
    for j in range(i+1,k):
        if not mask>>j&1:
            r=d[odds[i]][odds[j]]+match(mask|1<<i|1<<j)
            if r<best:
                best=r
    memo[mask]=best
    return best
print(total+(match(0) if odds else 0))

