import heapq
n,m,s,t=map(int,input().split())
edges=[tuple(map(int,input().split())) for _ in range(m)]
INF=float("inf")
best=INF
for L in sorted(set(w for u,v,w in edges)):
    g=[[] for _ in range(n+1)]
    for u,v,w in edges:
        if w>=L:
            g[u].append((v,w))
            g[v].append((u,w))
    mx=[INF]*(n+1)
    mx[s]=0
    h=[(0,s)]
    while h:
        d,x=heapq.heappop(h)
        if d>mx[x]:
            continue
        for y,w in g[x]:
            nd=max(d,w)
            if nd<mx[y]:
                mx[y]=nd
                heapq.heappush(h,(nd,y))
    if mx[t]<INF and mx[t]-L<best:
        best=mx[t]-L
print(best if best<INF else -1)

