n=int(input())
C=[list(map(int,input().split())) for _ in range(n)]
memo={}
def f(mask):
    if mask==(1<<n)-1:
        return 0
    if mask in memo:
        return memo[mask]
    i=0
    while mask>>i&1:
        i+=1
    best=0
    for j in range(i+1,n):
        if not mask>>j&1:
            v=C[i][j]+f(mask|1<<i|1<<j)
            if v>best:
                best=v
    memo[mask]=best
    return best
