n,m=map(int,input().split())
es=[tuple(map(int,input().split())) for _ in range(m)]
def acyclic(skip):
    ind=[0]*(n+1)
    g=[[] for _ in range(n+1)]
    for i,(u,v) in enumerate(es):
        if i!=skip:
            g[u].append(v)
            ind[v]+=1
    st=[v for v in range(1,n+1) if ind[v]==0]
    cnt=0
