from collections import deque
n,m=map(int,input().split())
es=[tuple(map(int,input().split())) for _ in range(m)]
def sp(skip):
    g=[[] for _ in range(n+1)]
    for i,(u,v) in enumerate(es):
        if i!=skip:
            g[u].append(v)
            g[v].append(u)
    dist=[-1]*(n+1)
    dist[1]=0
    q=deque([1])
    while q:
        x=q.popleft()
        for y in g[x]:
            if dist[y]<0:
                dist[y]=dist[x]+1
                q.append(y)
    return dist[n]
D=sp(-1)
