first=input().split()
n,m,k=map(int,first)
adj=[set() for _ in range(n+1)]
for _ in range(m):
    u,v=map(int,input().split())
    adj[u].add(v)
    adj[v].add(u)
for _ in range(k):
    input()
def best(rest):
    if not rest:
        return 0
    v=min(rest)
    r=best(rest-{v})
    for u in adj[v]:
        if u in rest and u!=v:
            c=1+best(rest-{v,u})
            if c>r:
                r=c
    return r
print("yes" if best(frozenset(range(1,n+1)))>k else "no")

