import sys
sys.setrecursionlimit(100000)
n,m=map(int,input().split())
g=[[] for _ in range(n+1)]
for _ in range(m):
    u,v=map(int,input().split())
    g[u].append(v)
memo={}
def lens(v):
    if v==n:
        return {0}
    if v in memo:
        return memo[v]
    r=set()
    for w in g[v]:
        r|={x+1 for x in lens(w)}
    memo[v]=r
    return r
print(len(lens(1)))

