    d1=cr(c,d,a)
    d2=cr(c,d,b)
    d3=cr(a,b,c)
    d4=cr(a,b,d)
    if ((d1>0)!=(d2>0)) and ((d3>0)!=(d4>0)):
        return True
    if d1==0 and on(c,d,a):
        return True
    if d2==0 and on(c,d,b):
        return True
    if d3==0 and on(a,b,c):
        return True
    if d4==0 and on(a,b,d):
        return True
    return False
