    i,j=pos
    t=0
    for sh in shapes:
        cells=[(i+di,j+dj) for di,dj in sh]
        if all(0<=a<2 and 0<=b<W and not grid[a][b] for a,b in cells):
            for a,b in cells:
                grid[a][b]=True
            t+=solve()
            for a,b in cells:
                grid[a][b]=False
    return t
print(solve() if n>0 else 1)

