from math import gcd
from collections import Counter
a=list(map(int,input().split()))
k=int(input())
c=Counter(gcd(x,k) for x in a)
keys=list(c)
ans=0
for i in range(len(keys)):
    for j in range(i,len(keys)):
        g1,g2=keys[i],keys[j]
        if (g1*g2)%k==0:
            if i==j:
                ans+=c[g1]*(c[g1]-1)//2
            else:
                ans+=c[g1]*c[g2]
print(ans)

