n=int(input())
a=list(map(int,input().split()))
ps=list(map(int,input().split()))
LOG=1
while (1<<LOG)<=n:
    LOG+=1
bit=[0]*(n+1)
for i in range(1,n+1):
    bit[i]+=1
    j=i+(i&-i)
    if j<=n:
        bit[j]+=bit[i]
def kth(k):
    pos=0
    for d in range(LOG,-1,-1):
        np=pos+(1<<d)
        if np<=n and bit[np]<k:
            pos=np
            k-=bit[np]
    return pos+1
def add(i,v):
    while i<=n:
        bit[i]+=v
        i+=i&-i
out=[]
for p in ps:
    i=kth(p)
    out.append(str(a[i-1]))
    add(i,-1)
print(" ".join(out))

