import sys
sys.setrecursionlimit(10000)
n,q=map(int,input().split())
a=list(map(int,input().split()))
N=1
while N<n:
    N*=2
sm=[0]*(2*N)
ad=[0]*(2*N)
st=[None]*(2*N)
ln=[0]*(2*N)
for i in range(n):
    sm[N+i]=a[i]
for i in range(N):
    ln[N+i]=1
for i in range(N-1,0,-1):
    sm[i]=sm[2*i]+sm[2*i+1]
    ln[i]=ln[2*i]+ln[2*i+1]
def aset(p,v):
    sm[p]=v*ln[p]
    st[p]=v
    ad[p]=0
def aadd(p,v):
    sm[p]+=v*ln[p]
    ad[p]+=v
def push(p):
    if st[p] is not None:
        aset(2*p,st[p])
        aset(2*p+1,st[p])
        st[p]=None
    if ad[p]:
        aadd(2*p,ad[p])
        aadd(2*p+1,ad[p])
        ad[p]=0
def upd(p,l,r,a,b,v,kind):
    if b<l or r<a:
        return
    if a<=l and r<=b:
        if kind==1:
            aadd(p,v)
        else:
            aset(p,v)
        return
    push(p)
    m=(l+r)//2
    upd(2*p,l,m,a,b,v,kind)
    upd(2*p+1,m+1,r,a,b,v,kind)
    sm[p]=sm[2*p]+sm[2*p+1]
def qry(p,l,r,a,b):
    if b<l or r<a:
        return 0
    if a<=l and r<=b:
        return sm[p]
    push(p)
    m=(l+r)//2
    return qry(2*p,l,m,a,b)+qry(2*p+1,m+1,r,a,b)
out=[]
for _ in range(q):
    t=list(map(int,input().split()))
    if t[0]==3:
        out.append(str(qry(1,0,N-1,t[1]-1,t[2]-1)))
    else:
        upd(1,0,N-1,t[1]-1,t[2]-1,t[3],t[0])
print("\n".join(out))

