import sys
sys.setrecursionlimit(10000)
M=10**9+7
n,q=map(int,input().split())
a=list(map(int,input().split()))
N=1
while N<n:
    N*=2
sm=[0]*(2*N)
mu=[1]*(2*N)
for i in range(n):
    sm[N+i]=a[i]%M
for i in range(N-1,0,-1):
    sm[i]=(sm[2*i]+sm[2*i+1])%M
def ap(p,v):
    sm[p]=sm[p]*v%M
    mu[p]=mu[p]*v%M
def push(p):
    if mu[p]!=1:
        ap(2*p,mu[p])
        ap(2*p+1,mu[p])
        mu[p]=1
def upd(p,l,r,a,b,v):
    if b<l or r<a:
        return
    if a<=l and r<=b:
        ap(p,v)
        return
    push(p)
    m=(l+r)//2
    upd(2*p,l,m,a,b,v)
    upd(2*p+1,m+1,r,a,b,v)
    sm[p]=(sm[2*p]+sm[2*p+1])%M
def qry(p,l,r,a,b):
    if b<l or r<a:
        return 0
    if a<=l and r<=b:
        return sm[p]
    push(p)
    m=(l+r)//2
    return (qry(2*p,l,m,a,b)+qry(2*p+1,m+1,r,a,b))%M
out=[]
