from functools import lru_cache
@lru_cache(None)
def f(i,j,tied):
    if i==a and j==b:
        return 1 if tied else 0
    t=0
    if i<a:
        t+=f(i+1,j,tied or (i+1==j))
    if j<b:
        t+=f(i,j+1,tied or (i==j+1))
    return t
print(f(0,0,False))

