from fractions import Fraction
n=int(input())
P=[tuple(map(int,input().split())) for _ in range(n)]
def ok(cx,cy,r2):
    return all((x-cx)**2+(y-cy)**2<=r2 for x,y in P)
best=None
if n==1:
    best=Fraction(0)
for i in range(n):
    for j in range(i+1,n):
        cx=Fraction(P[i][0]+P[j][0],2)
        cy=Fraction(P[i][1]+P[j][1],2)
        r2=(P[i][0]-cx)**2+(P[i][1]-cy)**2
        if ok(cx,cy,r2) and (best is None or r2<best):
            best=r2
        for k in range(j+1,n):
            ax,ay=P[i]
            bx,by=P[j]
            qx,qy=P[k]
            d=2*(ax*(by-qy)+bx*(qy-ay)+qx*(ay-by))
            if d==0:
                continue
            ux=Fraction((ax*ax+ay*ay)*(by-qy)+(bx*bx+by*by)*(qy-ay)+(qx*qx+qy*qy)*(ay-by),d)
            uy=Fraction((ax*ax+ay*ay)*(qx-bx)+(bx*bx+by*by)*(ax-qx)+(qx*qx+qy*qy)*(bx-ax),d)
            r2=(ax-ux)**2+(ay-uy)**2
            if ok(ux,uy,r2) and (best is None or r2<best):
                best=r2
print(best)

