P=[tuple(map(int,input().split())) for _ in range(n)]
area=sum(P[i][0]*P[(i+1)%n][1]-P[(i+1)%n][0]*P[i][1] for i in range(n))
if area<0:
    P.reverse()
def cross(o,a,b):
    return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
def inside(p,a,b,c):
    return cross(a,b,p)>=0 and cross(b,c,p)>=0 and cross(c,a,p)>=0
