    a=P[i-1]
    b=P[i]
    c=P[(i+1)%n]
    if cross(a,b,c)<=0:
        continue
    if any(inside(P[j],a,b,c) for j in range(n) if j not in (i-1,i,(i+1)%n) and j!=(i-1)%n):
        continue
    cnt+=1
print(cnt)

