n,m=map(int,input().split())
g=[[] for _ in range(n+1)]
for _ in range(m):
    u,v=map(int,input().split())
    g[u].append(v)
    g[v].append(u)
col=[-1]*(n+1)
ok=True
for s in range(1,n+1):
    if col[s]!=-1:
        continue
    col[s]=0
    dq=deque([s])
    while dq:
        x=dq.popleft()
        for y in g[x]:
            if col[y]==-1:
                col[y]=1-col[x]
                dq.append(y)
            elif col[y]==col[x]:
                ok=False
print(" ".join(str(col[i]) for i in range(1,n+1)) if ok else -1)

