n,q=map(int,input().split())
a=list(map(int,input().split()))
N=1
while N<n:
    N*=2
NEG=float("-inf")
mx=[NEG]*(2*N)
lz=[None]*(2*N)
for i in range(n):
    mx[N+i]=a[i]
for i in range(N-1,0,-1):
    mx[i]=max(mx[2*i],mx[2*i+1])
def ap(p,v):
    mx[p]=v
    lz[p]=v
def push(p):
    if lz[p] is not None:
        ap(2*p,lz[p])
        ap(2*p+1,lz[p])
        lz[p]=None
def upd(p,l,r,a1,b1,v):
    if b1<l or r<a1:
        return
    if a1<=l and r<=b1:
        ap(p,v)
        return
    push(p)
    m=(l+r)//2
    upd(2*p,l,m,a1,b1,v)
    upd(2*p+1,m+1,r,a1,b1,v)
    mx[p]=max(mx[2*p],mx[2*p+1])
def qry(p,l,r,a1,b1):
    if b1<l or r<a1:
        return NEG
    if a1<=l and r<=b1:
        return mx[p]
    push(p)
    m=(l+r)//2
    return max(qry(2*p,l,m,a1,b1),qry(2*p+1,m+1,r,a1,b1))
out=[]
