    t=list(map(int,input().split()))
    if t[0]==1:
        upd(1,0,N-1,t[1]-1,t[2]-1,t[3])
    else:
        out.append(str(qry(1,0,N-1,t[1]-1,t[2]-1)))
print("\n".join(out))

