n,m=map(int,input().split())
g=[[] for _ in range(n+1)]
for i in range(m):
    u,v=map(int,input().split())
    g[u].append((v,i))
    g[v].append((u,i))
for v in range(1,n+1):
    g[v].sort()
if m==0 or any(len(g[v])%2 for v in range(1,n+1)):
    print("-")
else:
    start=min(v for v in range(1,n+1) if g[v])
    seen={start}
    st=[start]
    while st:
        x=st.pop()
        for y,_ in g[x]:
            if y not in seen:
                seen.add(y)
                st.append(y)
    if any(g[v] and v not in seen for v in range(1,n+1)):
        print("-")
    else:
        used=[False]*m
        it=[0]*(n+1)
        stk=[start]
        circ=[]
        while stk:
            v=stk[-1]
            while it[v]<len(g[v]) and used[g[v][it[v]][1]]:
                it[v]+=1
            if it[v]==len(g[v]):
                circ.append(v)
                stk.pop()
            else:
                u,eid=g[v][it[v]]
                used[eid]=True
                stk.append(u)
        circ.reverse()
        print(" ".join(map(str,circ)))

