n=int(input())
S=[tuple(map(int,input().split())) for _ in range(n)]
def cr(ox,oy,ax,ay,bx,by):
    return (ax-ox)*(by-oy)-(ay-oy)*(bx-ox)
def on(px,py,qx,qy,rx,ry):
    return min(px,qx)<=rx<=max(px,qx) and min(py,qy)<=ry<=max(py,qy)
def inter(s,t):
    x1,y1,x2,y2=s
    x3,y3,x4,y4=t
    d1=cr(x3,y3,x4,y4,x1,y1)
    d2=cr(x3,y3,x4,y4,x2,y2)
    d3=cr(x1,y1,x2,y2,x3,y3)
    d4=cr(x1,y1,x2,y2,x4,y4)
    if ((d1>0)!=(d2>0)) and ((d3>0)!=(d4>0)):
        return True
    if d1==0 and on(x3,y3,x4,y4,x1,y1):
        return True
    if d2==0 and on(x3,y3,x4,y4,x2,y2):
        return True
    if d3==0 and on(x1,y1,x2,y2,x3,y3):
        return True
    if d4==0 and on(x1,y1,x2,y2,x4,y4):
        return True
    return False
out=[]
for i in range(n):
    for j in range(i+1,n):
        if inter(S[i],S[j]):
            out.append(f"{i+1} {j+1}")
print("\n".join(out) if out else "-")

