import sys
sys.setrecursionlimit(10000)
first=input().split()
n,sr,sc=int(first[0]),int(first[1])-1,int(first[2])-1
D=((-2,-1),(-2,1),(-1,-2),(-1,2),(1,-2),(1,2),(2,-1),(2,1))
board=[[-1]*n for _ in range(n)]
path=[]
def deg(r,c):
    t=0
    for dr,dc in D:
        nr,nc=r+dr,c+dc
        if 0<=nr<n and 0<=nc<n and board[nr][nc]<0:
            t+=1
    return t
def dfs(r,c,k):
    board[r][c]=k
    path.append((r,c))
    if k==n*n-1:
        return True
    cand=[]
    for idx in range(8):
        nr,nc=r+D[idx][0],c+D[idx][1]
        if 0<=nr<n and 0<=nc<n and board[nr][nc]<0:
            cand.append((deg(nr,nc),idx,nr,nc))
    cand.sort()
    for _,_,nr,nc in cand:
        if dfs(nr,nc,k+1):
            return True
    board[r][c]=-1
    path.pop()
    return False
if dfs(sr,sc,0):
    print(' '.join('%d %d'%(r+1,c+1) for r,c in path))
else:
    print(-1)

