from collections import Counter
s=input().strip()
c=Counter(s)
n=len(s)
if max(c.values())>(n+1)//2:
    print(-1)
else:
    res=[]
    prev=''
    for _ in range(n):
        best=None
        for ch in sorted(c):
            if c[ch]>0 and ch!=prev:
                if best is None or c[ch]>c[best]:
                    best=ch
        res.append(best)
        c[best]-=1
        prev=best
    print(''.join(res))

