words=input().split()
lines=[]
cur=[]
ln=0
for w in words:
    if cur and ln+1+len(w)>W:
        lines.append(cur)
        cur=[w]
        ln=len(w)
    else:
        ln=ln+1+len(w) if cur else len(w)
        cur.append(w)
if cur:
    lines.append(cur)
for idx,ws in enumerate(lines):
    if idx==len(lines)-1 or len(ws)==1:
        print(' '.join(ws))
    else:
        total=W-sum(len(x) for x in ws)
        gaps=len(ws)-1
        base=total//gaps
        extra=total%gaps
        s=''
        for j,x in enumerate(ws):
            s+=x
            if j<gaps:
                s+=' '*(base+(1 if j<extra else 0))
        print(s)

