from collections import deque
first=input().split()
s,t=first[0],first[1]
k=int(input())
ws=set(input().strip() for _ in range(k))
ws.add(s)
ws.add(t)
def adj(w):
    return sorted(x for x in ws if len(x)==len(w) and sum(1 for a,b in zip(x,w) if a!=b)==1)
distT={t:0}
q=deque([t])
while q:
    w=q.popleft()
    for x in adj(w):
        if x not in distT:
            distT[x]=distT[w]+1
            q.append(x)
if s not in distT:
    print(-1)
else:
    cur=s
    path=[s]
    while cur!=t:
        for x in adj(cur):
            if distT.get(x,-1)==distT[cur]-1:
                path.append(x)
                cur=x
                break
    print(' '.join(path))

