from collections import deque
first=input().split()
h,w=int(first[0]),int(first[1])
g=[input().strip() for _ in range(h)]
sr=sc=gr=gc=-1
for i in range(h):
    for j in range(w):
        if g[i][j]=='S':
            sr,sc=i,j
        elif g[i][j]=='G':
            gr,gc=i,j
INF=float('inf')
d=[[INF]*w for _ in range(h)]
d[gr][gc]=0
q=deque([(gr,gc)])
while q:
    r,c=q.popleft()
    for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
        nr,nc=r+dr,c+dc
        if 0<=nr<h and 0<=nc<w and g[nr][nc]!='#' and d[nr][nc]==INF:
            d[nr][nc]=d[r][c]+1
            q.append((nr,nc))
if d[sr][sc]==INF:
    print(-1)
else:
    r,c=sr,sc
    path=[(r,c)]
    while (r,c)!=(gr,gc):
        for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and d[nr][nc]==d[r][c]-1:
                r,c=nr,nc
                break
        path.append((r,c))
    print(' '.join('%d %d'%(a+1,b+1) for a,b in path))

