import heapq
first=input().split()
n,m=int(first[0]),int(first[1])
g=[[] for _ in range(n+1)]
for _ in range(m):
    u,v,w=map(int,input().split())
    g[u].append((v,w))
    g[v].append((u,w))
INF=float('inf')
dist=[INF]*(n+1)
dist[1]=0
h=[(0,1)]
while h:
    d,v=heapq.heappop(h)
    if d>dist[v]:
        continue
    for w,c in g[v]:
        if d+c<dist[w]:
            dist[w]=d+c
            heapq.heappush(h,(d+c,w))
par=[0]*(n+1)
for v in range(2,n+1):
    if dist[v]==INF:
        par[v]=-1
    else:
        best=-1
        for u,c in g[v]:
            if dist[u]+c==dist[v] and (best==-1 or u<best):
                best=u
        par[v]=best
print(' '.join(str(par[v]) for v in range(1,n+1)))

