from collections import deque
first=input().split()
h,w=int(first[0]),int(first[1])
g=[input().strip() for _ in range(h)]
INF=float('inf')
fd=[[INF]*w for _ in range(h)]
q=deque()
sr=sc=gr=gc=-1
for i in range(h):
    for j in range(w):
        if g[i][j]=='F':
            fd[i][j]=0
            q.append((i,j))
        elif g[i][j]=='S':
            sr,sc=i,j
        elif g[i][j]=='G':
            gr,gc=i,j
while q:
    r,c=q.popleft()
    for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
        nr,nc=r+dr,c+dc
        if 0<=nr<h and 0<=nc<w and g[nr][nc]!='#' and fd[nr][nc]==INF:
            fd[nr][nc]=fd[r][c]+1
            q.append((nr,nc))
pd=[[INF]*w for _ in range(h)]
pd[sr][sc]=0
q=deque([(sr,sc)])
while q:
    r,c=q.popleft()
    for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
        nr,nc=r+dr,c+dc
        if 0<=nr<h and 0<=nc<w and g[nr][nc]!='#' and pd[nr][nc]==INF and pd[r][c]+1<fd[nr][nc]:
            pd[nr][nc]=pd[r][c]+1
            q.append((nr,nc))
if pd[gr][gc]==INF:
    print(-1)
else:
    r,c=gr,gc
    path=[(r,c)]
    while (r,c)!=(sr,sc):
        for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and pd[nr][nc]==pd[r][c]-1:
                r,c=nr,nc
                break
        path.append((r,c))
    path.reverse()
    print(' '.join('%d %d'%(a+1,b+1) for a,b in path))

