from collections import deque
first=input().split()
n,m=int(first[0]),int(first[1])
g=[[] for _ in range(n+1)]
for _ in range(m):
    u,v=map(int,input().split())
    g[u].append(v)
    g[v].append(u)
color=[-1]*(n+1)
comps=[]
ok=True
for s in range(1,n+1):
    if color[s]>=0:
        continue
    color[s]=0
    q=deque([s])
    a=[s]
    b=[]
    while q:
        x=q.popleft()
        for y in g[x]:
            if color[y]<0:
                color[y]=1-color[x]
                if color[y]==0:
                    a.append(y)
                else:
                    b.append(y)
                q.append(y)
            elif color[y]==color[x]:
                ok=False
    comps.append((sorted(a),sorted(b)))
if not ok:
    print(-1)
else:
    c=len(comps)
    best=None
    for mask in range(1<<c):
        t1=[]
        for i in range(c):
            t1.extend(comps[i][0] if mask>>i&1 else comps[i][1])
        t1.sort()
        key=(abs(2*len(t1)-n),t1)
        if best is None or key<best:
            best=key
    print(' '.join(map(str,best[1])) if best[1] else 'none')

