import sys
sys.setrecursionlimit(10000)
from collections import defaultdict
first=input().split()
n,m=int(first[0]),int(first[1])
g=[[] for _ in range(n+1)]
es=[]
for i in range(m):
    u,v=map(int,input().split())
    g[u].append((v,i))
    g[v].append((u,i))
    es.append((u,v))
tin=[-1]*(n+1)
low=[0]*(n+1)
timer=[0]
bridges=set()
def dfs(v,pe):
    tin[v]=low[v]=timer[0]
    timer[0]+=1
    for w,ei in g[v]:
        if ei==pe:
            continue
        if tin[w]>=0:
            if tin[w]<low[v]:
                low[v]=tin[w]
        else:
            dfs(w,ei)
            if low[w]<low[v]:
                low[v]=low[w]
            if low[w]>tin[v]:
                bridges.add(ei)
for s in range(1,n+1):
    if tin[s]<0:
        dfs(s,-1)
p=list(range(n+1))
def f(x):
    while p[x]!=x:
        p[x]=p[p[x]]
        x=p[x]
    return x
for i in range(m):
    if i not in bridges:
        p[f(es[i][0])]=f(es[i][1])
comp=defaultdict(list)
for v in range(1,n+1):
    comp[f(v)].append(v)
for gp in sorted(comp.values(),key=lambda a:a[0]):
    print(' '.join(map(str,gp)))

