from collections import deque
a,b,c=map(int,input().split())
ops=["FA","FB","EA","EB","PAB","PBA"]
def nxt(s,k):
    x,y=s
    if k==0:
        return (a,y)
    if k==1:
        return (x,b)
    if k==2:
        return (0,y)
    if k==3:
        return (x,0)
    if k==4:
        d=min(x,b-y)
        return (x-d,y+d)
    d=min(y,a-x)
    return (x+d,y-d)
par={(0,0):None}
q=deque([(0,0)])
goal=None
while q:
    s=q.popleft()
    if s[0]==c or s[1]==c:
        goal=s
        break
    for k in range(6):
        u=nxt(s,k)
        if u not in par:
            par[u]=(s,k)
            q.append(u)
if goal is None:
    print(-1)
else:
    res=[]
    cur=goal
    while par[cur] is not None:
        p,k=par[cur]
        res.append(ops[k])
        cur=p
    res.reverse()
    print(" ".join(res) if res else "none")

