from collections import deque
n,m=map(int,input().split())
g=[[] for _ in range(n+1)]
E=set()
for _ in range(m):
    u,v=map(int,input().split())
    g[u].append(v)
    g[v].append(u)
    E.add((min(u,v),max(u,v)))
color=[-1]*(n+1)
color[1]=0
q=deque([1])
