from collections import deque
n=int(input())
E=[tuple(map(int,input().split())) for _ in range(n-1)]
deg=[0]*(n+1)
for u,v in E:
    deg[u]+=1
    deg[v]+=1
best=None
for L in range(1,n+1):
    if deg[L]!=1:
        continue
    g=[[] for _ in range(n+1)]
    for u,v in E:
        if u==L or v==L:
            continue
        g[u].append(v)
        g[v].append(u)
    dm=0
    for s in range(1,n+1):
        if s==L:
            continue
        d=[-1]*(n+1)
        d[s]=0
        q=deque([s])
        while q:
            x=q.popleft()
            for y in g[x]:
                if d[y]<0:
                    d[y]=d[x]+1
                    q.append(y)
        for v in range(1,n+1):
            if v!=L and d[v]>dm:
                dm=d[v]
    if best is None or dm<best[0]:
        best=(dm,L)
print(best[1],best[0])

