        cid+=1
        for u in range(1,n+1):
            if reach[v][u] and reach[u][v]:
                comp[u]=cid
hasin=[False]*(cid+1)
for u,v in es:
    if comp[u]!=comp[v]:
        hasin[comp[v]]=True
best={}
for v in range(1,n+1):
    c=comp[v]
    if c not in best:
        best[c]=v
res=[best[c] for c in range(1,cid+1) if not hasin[c]]
print(" ".join(map(str,sorted(res))))

