import heapq
n,m,k=map(int,input().split())
g=[[] for _ in range(n+1)]
rg=[[] for _ in range(n+1)]
for _ in range(m):
    u,v=map(int,input().split())
    g[u].append(v)
    rg[v].append(u)
anc=[False]*(n+1)
st=[k]
while st:
    x=st.pop()
    for y in rg[x]:
        if not anc[y]:
            anc[y]=True
            st.append(y)
def kahn(nodes):
    inset=set(nodes)
    deg={}
    for v in nodes:
        deg[v]=0
    for v in nodes:
        for u in rg[v]:
            if u in inset:
                deg[v]+=1
    h=[v for v in nodes if deg[v]==0]
    heapq.heapify(h)
    out=[]
    while h:
        x=heapq.heappop(h)
        out.append(x)
        for y in g[x]:
            if y in inset:
                deg[y]-=1
                if deg[y]==0:
                    heapq.heappush(h,y)
    return out
A=[v for v in range(1,n+1) if anc[v]]
R=[v for v in range(1,n+1) if v!=k and not anc[v]]
print(" ".join(map(str,kahn(A)+[k]+kahn(R))))

