    ssum=shortsum(d)*L
    lsum=longsum(d)*S
    if ssum>lsum:
        st=1
    elif ssum<lsum:
        st=-1
    else:
        st=0
    states.append(st)
    days.append(d)
crossings=[]
for idx in range(1,len(states)):
    if states[idx-1]!=0 and states[idx]!=0 and states[idx-1]*states[idx]<0:
        crossings.append(days[idx])
print(" ".join(map(str,crossings)) if crossings else "NONE")

