    grid=[[False]*n for _ in range(3)] if n>0 else []
    results=[]
    def find_empty():
        for r in range(3):
            for c in range(n):
                if not grid[r][c]:
                    return (r,c)
        return None
    def backtrack(dominoes):
        pos=find_empty()
        if pos is None:
            results.append(list(dominoes))
            return
        r,c=pos
        if c+1<n and not grid[r][c+1]:
            grid[r][c]=True
            grid[r][c+1]=True
            dominoes.append((r,c,r,c+1))
            backtrack(dominoes)
            dominoes.pop()
            grid[r][c]=False
            grid[r][c+1]=False
        if r+1<3 and not grid[r+1][c]:
            grid[r][c]=True
            grid[r+1][c]=True
            dominoes.append((r,c,r+1,c))
            backtrack(dominoes)
            dominoes.pop()
            grid[r][c]=False
            grid[r+1][c]=False
    if n==0:
