def target_pattern(n, start):
    other = "1" if start == "0" else "0"
    return "".join(start if i % 2 == 0 else other for i in range(n))


def mismatches(s, t):
    typeA = []
    typeB = []
    for i in range(len(s)):
        sc = s[i]
        tc = t[i]
        if sc == tc:
            continue
        if tc == "1":
            typeA.append(i + 1)
        else:
            typeB.append(i + 1)
    return typeA, typeB


s = input().strip()
n = len(s)
count0 = s.count("0")
count1 = n - count0
candidates = []
for start in ["0", "1"]:
    t = target_pattern(n, start)
    need0 = t.count("0")
    need1 = n - need0
    if need0 == count0 and need1 == count1:
        typeA, typeB = mismatches(s, t)
        if len(typeA) == len(typeB):
            candidates.append((len(typeA), start, typeA, typeB))
if not candidates:
    print("impossible")
else:
    candidates.sort(key=lambda c: (c[0], c[1]))
    swaps, start, typeA, typeB = candidates[0]
    if swaps == 0:
        print(0)
    else:
        print(swaps)
        for x, y in zip(typeA, typeB):
            print(x, y)

