def at_most(a, k):
    if k < 0:
        return 0
    count = {}
    left = 0
    total = 0
    for right in range(len(a)):
        count[a[right]] = count.get(a[right], 0) + 1
        while len(count) > k:
            count[a[left]] -= 1
            if count[a[left]] == 0:
                del count[a[left]]
            left += 1
        total += right - left + 1
    return total


