def main():
    q=int(input())
    buy_heap=[]
    sell_heap=[]
    remaining={}
    for idx in range(q):
        parts=input().split()
        typ=parts[0]; p=int(parts[1]); qty=int(parts[2])
        if typ=="buy":
            while qty>0 and sell_heap and sell_heap[0][0]<=p:
                sp,sidx=sell_heap[0]
                avail=remaining[sidx][2]
                trade=min(qty,avail)
                qty-=trade
                remaining[sidx][2]-=trade
                if remaining[sidx][2]==0:
                    heapq.heappop(sell_heap)
                    del remaining[sidx]
            if qty>0:
                remaining[idx]=["buy",p,qty]
                heapq.heappush(buy_heap,(-p,idx))
        else:
            while qty>0 and buy_heap and -buy_heap[0][0]>=p:
                bp_neg,bidx=buy_heap[0]
                avail=remaining[bidx][2]
                trade=min(qty,avail)
