                remaining[bidx][2]-=trade
                if remaining[bidx][2]==0:
                    heapq.heappop(buy_heap)
                    del remaining[bidx]
            if qty>0:
                remaining[idx]=["sell",p,qty]
                heapq.heappush(sell_heap,(p,idx))
